package com.mushafi.app;

import android.app.Activity;
import android.content.SharedPreferences;
import android.os.CancellationSignal;
import android.os.Handler;
import android.os.Looper;
import android.webkit.WebView;
import androidx.credentials.*;
import androidx.credentials.exceptions.*;
import com.google.android.libraries.identity.googleid.GetGoogleIdOption;
import com.google.android.libraries.identity.googleid.GoogleIdTokenCredential;
import com.google.firebase.FirebaseApp;
import com.google.firebase.auth.*;
import com.google.firebase.firestore.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.Executor;

/** Google identity and per-UID transactional sync. Tokens never cross the WebView bridge. */
public final class CloudSyncController {
 private static volatile CloudSyncController live;
 static boolean retryLive(){CloudSyncController c=live;if(c==null||c.closed)return false;c.retry();return true;}
 private final Activity activity;private final WebView web;private final Handler main=new Handler(Looper.getMainLooper());
 private final FirebaseAuth auth;private final FirebaseFirestore db;private final SharedPreferences prefs;private final String device;
 private ListenerRegistration listener;private volatile String uid="",status="signedOut",error="",pending="",remote="",pendingBaseline=CloudPayloadMerge.EMPTY;private volatile long remoteRevision=0,pendingBase=0,lastSync=0,generation=0;private volatile boolean initialized=false,writing=false,loginBusy=false,closed=false;private CancellationSignal signInSignal;private volatile boolean deleteBusy=false,deletionSucceeded=false,accountRemoved=false;private volatile String deleteError="";
 public CloudSyncController(Activity a,WebView w){activity=a;web=w;live=this;prefs=a.getSharedPreferences("cloud_sync",0);String id=prefs.getString("device",null);if(id==null){id=UUID.randomUUID().toString();prefs.edit().putString("device",id).commit();}device=id;if(FirebaseApp.getApps(a).isEmpty())FirebaseApp.initializeApp(a);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();auth.addAuthStateListener(authListener);}
 private final FirebaseAuth.AuthStateListener authListener=firebaseAuth->main.post(this::accountChanged);
 private String key(String suffix){return uid+"_"+suffix;}
 private boolean active(String user,long gen){return !closed&&generation==gen&&uid.equals(user)&&auth.getCurrentUser()!=null&&user.equals(auth.getCurrentUser().getUid());}
 private void accountChanged(){accountChanged(false);}
 private void accountChanged(boolean force){if(deleteBusy)return;FirebaseUser user=auth.getCurrentUser();String next=user==null?"":user.getUid();if(!force&&next.equals(uid)&&(!next.isEmpty()||status.equals("signedOut"))){emit();return;}generation++;if(listener!=null){listener.remove();listener=null;}uid=next;writing=false;initialized=false;remote="";remoteRevision=0;error="";pending=uid.isEmpty()?"":prefs.getString(key("pending"),"");pendingBase=uid.isEmpty()?0:prefs.getLong(key("base"),0);pendingBaseline=uid.isEmpty()?CloudPayloadMerge.EMPTY:prefs.getString(key("basePayload"),prefs.getString(key("ackPayload"),CloudPayloadMerge.EMPTY));lastSync=uid.isEmpty()?0:prefs.getLong(key("lastSync"),0);if(!pending.isEmpty())CloudSyncJobService.schedule(activity);status=uid.isEmpty()?"signedOut":"connecting";if(!uid.isEmpty()&&prefs.getBoolean(key("deletePending"),false)){status="deletionPending";emit();return;}emit();if(uid.isEmpty())return;final String userId=uid;final long gen=generation;
  listener=document(userId).addSnapshotListener(MetadataChanges.INCLUDE,(snapshot,failure)->{if(!active(userId,gen))return;if(failure!=null){status="error";error=explain(failure);emit();return;}if(snapshot==null||snapshot.getMetadata().hasPendingWrites())return;if(snapshot.getMetadata().isFromCache()){if(!initialized){status="offline";emit();}return;}if(!snapshot.exists()&&(remoteRevision>0||prefs.getLong(userId+"_lastSync",0)>0)){removedOnAnotherDevice(userId);return;}initialized=true;remote=snapshot.exists()&&snapshot.getString("payload")!=null?snapshot.getString("payload"):"";Long rev=snapshot.getLong("revision");remoteRevision=rev==null?0:rev;if(writing){status="syncing";emit();return;}if(!pending.isEmpty()){if(pending.equals(remote)){acknowledge();return;}flush();}else{status=remote.isEmpty()?"empty":"ready";error="";if(!remote.isEmpty()){lastSync=System.currentTimeMillis();prefs.edit().putLong(key("lastSync"),lastSync).apply();}emit();}});
 }
 private DocumentReference document(String user){return db.collection("users").document(user).collection("mushafi").document("state");}
 public void signIn(){main.post(()->{if(loginBusy||deleteBusy||closed)return;deletionSucceeded=false;accountRemoved=false;loginBusy=true;error="";emit();signInSignal=new CancellationSignal();String nonce=UUID.randomUUID().toString()+UUID.randomUUID();GetGoogleIdOption option=new GetGoogleIdOption.Builder().setFilterByAuthorizedAccounts(false).setServerClientId(activity.getString(activity.getResources().getIdentifier("default_web_client_id","string",activity.getPackageName()))).setAutoSelectEnabled(false).setNonce(nonce).build();GetCredentialRequest request=new GetCredentialRequest.Builder().addCredentialOption(option).build();Executor executor=command->main.post(command);try{CredentialManager.create(activity).getCredentialAsync(activity,request,signInSignal,executor,new CredentialManagerCallback<GetCredentialResponse,GetCredentialException>(){public void onResult(GetCredentialResponse result){try{Credential credential=result.getCredential();if(!(credential instanceof CustomCredential)||!GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL.equals(credential.getType()))throw new IllegalStateException("provider");String token=GoogleIdTokenCredential.createFrom(credential.getData()).getIdToken();auth.signInWithCredential(GoogleAuthProvider.getCredential(token,null)).addOnCompleteListener(task->{loginBusy=false;if(!task.isSuccessful()){error="تعذر الدخول بقوقل. تحقق من الاتصال وإعدادات الحساب ثم أعد المحاولة.";emit();}});}catch(Exception e){loginBusy=false;error="تعذر قراءة نتيجة تسجيل قوقل. أعد المحاولة.";emit();}}public void onError(GetCredentialException e){loginBusy=false;error=e instanceof GetCredentialCancellationException?"":e instanceof NoCredentialException?"لم يتوفر حساب قوقل. أضف حسابك للجهاز وحدّث خدمات Google Play ثم أعد المحاولة.":"تعذر فتح تسجيل قوقل. تحقق من الاتصال وخدمات Google Play.";emit();}});}catch(Exception e){loginBusy=false;error="تسجيل قوقل يحتاج خدمات Google Play محدثة على هذا الجهاز.";emit();}});}
 public void push(String payload,long expectedRevision){push(payload,expectedRevision,uid);}
 public void push(String payload,long expectedRevision,String expectedUser){push(payload,expectedRevision,expectedUser,null);}
 public void push(String payload,long expectedRevision,String expectedUser,String baseline){
  if(!validPayload(payload)||expectedRevision<0||(baseline!=null&&!baseline.isEmpty()&&!validPayload(baseline)))return;
  Runnable journal=()->{if(!uid.equals(expectedUser)||deleteBusy||prefs.getBoolean(key("deletePending"),false)||uid.isEmpty()||closed||auth.getCurrentUser()==null||!uid.equals(auth.getCurrentUser().getUid()))return;
   if(pending.equals(payload))return;
   if(pending.isEmpty()||expectedRevision>pendingBase)pendingBaseline=baseline!=null&&!baseline.isEmpty()?baseline:expectedRevision==remoteRevision&&!remote.isEmpty()?remote:prefs.getString(key("ackPayload"),CloudPayloadMerge.EMPTY);
   pending=payload;pendingBase=Math.max(expectedRevision,pendingBase);prefs.edit().putString(key("pending"),pending).putString(key("op"),CloudPayloadMerge.nextOperation(prefs)).putString(key("basePayload"),pendingBaseline).putLong(key("base"),pendingBase).commit();error="";status="pending";CloudSyncJobService.schedule(activity);emit();main.post(this::flush);
  };
  if(Looper.myLooper()==Looper.getMainLooper())journal.run();else{java.util.concurrent.FutureTask<Void> task=new java.util.concurrent.FutureTask<>(journal,null);main.post(task);try{task.get(5,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception ignored){}}
 }
 private boolean validPayload(String p){try{if(p==null||p.getBytes("UTF-8").length>750000)return false;JSONObject j=new JSONObject(p);return j.optInt("version")==1&&j.optString("format").equals("mushafi-backup")&&j.optJSONObject("data")!=null;}catch(Exception e){return false;}}
 private void flush(){if(deleteBusy||prefs.getBoolean(key("deletePending"),false)||closed||uid.isEmpty()||pending.isEmpty()||writing||!initialized||CloudSyncJobService.uploading)return;
  final String user=uid,input=pending,baseline=pendingBaseline,op=prefs.getString(key("op"),"").isEmpty()?CloudPayloadMerge.nextOperation(prefs):prefs.getString(key("op"),"");prefs.edit().putString(key("op"),op).commit();final long gen=generation;writing=true;status="syncing";emit();
  db.runTransaction(tx->{try{if(!active(user,gen)||prefs.getBoolean(user+"_deletePending",false))throw new FirebaseFirestoreException("session changed",FirebaseFirestoreException.Code.ABORTED);
   DocumentReference ref=document(user);DocumentSnapshot existing=tx.get(ref);Long rev=existing.getLong("revision");long current=rev==null?0:rev;String server=existing.getString("payload");if(CloudPayloadMerge.applied(server,op))return new JSONObject().put("revision",current).put("payload",server);long next=current+1;String merged=CloudPayloadMerge.record(CloudPayloadMerge.merge(baseline,input,server),server,op);if(!validPayload(merged))throw new FirebaseFirestoreException("payload too large",FirebaseFirestoreException.Code.INVALID_ARGUMENT);
   Map<String,Object> data=new HashMap<>();data.put("payload",merged);data.put("revision",next);data.put("updatedAt",FieldValue.serverTimestamp());data.put("device",device);tx.set(ref,data);return new JSONObject().put("revision",next).put("payload",merged);
  }catch(JSONException e){throw new FirebaseFirestoreException("invalid payload",FirebaseFirestoreException.Code.INVALID_ARGUMENT,e);}}).addOnSuccessListener(result->{if(!active(user,gen))return;writing=false;long revision=result.optLong("revision");String merged=result.optString("payload");lastSync=System.currentTimeMillis();prefs.edit().putLong(key("ackRevision"),revision).putString(key("ackPayload"),merged).putString(key("ackInput"),input).putLong(key("lastSync"),lastSync).commit();if(remoteRevision<=revision){remote=merged;remoteRevision=revision;}
   if(pending.equals(input)&&op.equals(prefs.getString(key("op"),""))){pending="";pendingBase=remoteRevision;pendingBaseline=remote;prefs.edit().remove(key("pending")).remove(key("op")).remove(key("basePayload")).putLong(key("base"),pendingBase).commit();status="synced";error="";}
   else{pendingBase=revision;pendingBaseline=pending.equals(input)?baseline:input;prefs.edit().putLong(key("base"),revision).putString(key("basePayload"),pendingBaseline).commit();status="pending";}
   emit();if(!pending.isEmpty())flush();
  }).addOnFailureListener(failure->{if(!active(user,gen))return;writing=false;status="error";error=explain(failure);CloudSyncJobService.schedule(activity);main.postDelayed(()->{if(active(user,gen)&&!pending.isEmpty())retry();},10000);emit();});
 }
 private void acknowledge(){String input=pending;pending="";pendingBase=remoteRevision;pendingBaseline=remote;lastSync=System.currentTimeMillis();prefs.edit().remove(key("pending")).remove(key("op")).remove(key("basePayload")).putLong(key("base"),remoteRevision).putLong(key("lastSync"),lastSync).putLong(key("ackRevision"),remoteRevision).putString(key("ackPayload"),remote).putString(key("ackInput"),input).commit();status="synced";error="";emit();}
 public void retry(){main.post(()->{if(deleteBusy||prefs.getBoolean(key("deletePending"),false)||uid.isEmpty()||closed)return;FirebaseUser current=auth.getCurrentUser();if(current!=null)current.reload().addOnFailureListener(failure->{if(failure instanceof FirebaseAuthInvalidUserException){accountRemoved=true;auth.signOut();accountChanged(true);}});if(writing){emit();return;}accountChanged(true);});}
 public void resolve(boolean local){resolve(local,uid);}
 public void resolve(boolean local,String expectedUser){main.post(()->{if(!uid.equals(expectedUser)||deleteBusy||prefs.getBoolean(key("deletePending"),false)||uid.isEmpty()||!initialized)return;error="";if(local){flush();}else{pending="";pendingBase=remoteRevision;prefs.edit().remove(key("pending")).putLong(key("base"),remoteRevision).commit();status=remote.isEmpty()?"empty":"ready";emit();}});}
 public void signOut(){main.post(()->{if(deleteBusy)return;if(signInSignal!=null)signInSignal.cancel();generation++;auth.signOut();try{KhatmaScheduler.clear(activity);PrayerSettings settings=PrayerSettings.load(activity);settings.json.put("enabled",false);settings.save(activity);PrayerScheduler.schedule(activity);}catch(Exception ignored){}accountChanged();try{CredentialManager.create(activity).clearCredentialStateAsync(new ClearCredentialStateRequest(),null,command->main.post(command),new CredentialManagerCallback<Void,ClearCredentialException>(){public void onResult(Void result){}public void onError(ClearCredentialException error){}});}catch(Exception ignored){} });}
 private void removedOnAnotherDevice(String userId){generation++;if(listener!=null){listener.remove();listener=null;}SharedPreferences.Editor edit=prefs.edit();for(String name:prefs.getAll().keySet())if(name.startsWith(userId+"_"))edit.remove(name);edit.commit();uid="";pending="";remote="";remoteRevision=0;initialized=false;writing=false;accountRemoved=true;auth.signOut();status="signedOut";try{KhatmaScheduler.clear(activity);PrayerSettings settings=PrayerSettings.load(activity);settings.json.put("enabled",false);settings.save(activity);PrayerScheduler.schedule(activity);}catch(Exception ignored){}emit();}
 public void acknowledgeDeletion(){main.post(()->{deletionSucceeded=false;accountRemoved=false;if(uid.isEmpty())status="signedOut";});}
 public void deleteAccount(){main.post(()->{FirebaseUser user=auth.getCurrentUser();if(user==null||deleteBusy||loginBusy||closed)return;deleteBusy=true;deleteError="";generation++;writing=false;if(listener!=null){listener.remove();listener=null;}status="deleting";emit();signInSignal=new CancellationSignal();try{GetGoogleIdOption option=new GetGoogleIdOption.Builder().setFilterByAuthorizedAccounts(false).setServerClientId(activity.getString(activity.getResources().getIdentifier("default_web_client_id","string",activity.getPackageName()))).setAutoSelectEnabled(false).setNonce(UUID.randomUUID().toString()+UUID.randomUUID()).build();CredentialManager.create(activity).getCredentialAsync(activity,new GetCredentialRequest.Builder().addCredentialOption(option).build(),signInSignal,command->main.post(command),new CredentialManagerCallback<GetCredentialResponse,GetCredentialException>(){public void onResult(GetCredentialResponse result){try{Credential credential=result.getCredential();if(!(credential instanceof CustomCredential)||!GoogleIdTokenCredential.TYPE_GOOGLE_ID_TOKEN_CREDENTIAL.equals(credential.getType()))throw new IllegalStateException("provider");String token=GoogleIdTokenCredential.createFrom(credential.getData()).getIdToken();user.reauthenticate(GoogleAuthProvider.getCredential(token,null)).addOnSuccessListener(v->eraseAccount(user)).addOnFailureListener(e->deletionFailed("لم يتم حذف الحساب. اختر حساب قوقل نفسه للتحقق من الملكية ثم أعد المحاولة."));}catch(Exception e){deletionFailed("تعذر التحقق من ملكية الحساب. لم يتم الحذف.");}}public void onError(GetCredentialException e){deletionFailed(e instanceof GetCredentialCancellationException?"أُلغي التحقق؛ لم تكتمل عملية الحذف.":"تعذر فتح التحقق بقوقل. أعد المحاولة مع اتصال بالإنترنت.");}});}catch(Exception e){deletionFailed("تعذر بدء التحقق من الحساب. أعد المحاولة لاحقًا.");}});}
 private void eraseAccount(FirebaseUser user){ChallengeClient.eraseBeforeAccount(activity,user,()->eraseCloudAccount(user),()->deletionFailed("لم تكتمل إزالة بيانات المنافسات. تحقق من الاتصال ثم أعد تأكيد الحذف."));}
 private void eraseCloudAccount(FirebaseUser user){final String userId=user.getUid();if(closed||!userId.equals(uid)||auth.getCurrentUser()==null||!userId.equals(auth.getCurrentUser().getUid())){deletionFailed("تغيرت جلسة الحساب؛ أعد تأكيد الحذف.");return;}prefs.edit().putBoolean(userId+"_deletePending",true).commit();db.waitForPendingWrites().addOnSuccessListener(v->document(userId).delete().addOnSuccessListener(erased->{prefs.edit().putString(userId+"_deleteStage","cloudErased").commit();user.delete().addOnSuccessListener(done->finishAccountDeletion(userId)).addOnFailureListener(e->deletionFailed("حُذفت بيانات المزامنة، ولم يكتمل حذف الحساب. أعد تأكيد الدخول لإكمال الحذف. المزامنة موقوفة لحماية عملية الحذف."));}).addOnFailureListener(e->deletionFailed("لم تكتمل إزالة بيانات السحابة. تحقق من الاتصال وقواعد خدمة المزامنة ثم أعد محاولة الحذف."))).addOnFailureListener(e->deletionFailed("تعذر إنهاء المزامنة قبل الحذف. أعد المحاولة عند توفر الاتصال."));}
 private void deletionFailed(String message){deleteBusy=false;deleteError=message;if(!uid.isEmpty()&&prefs.getBoolean(key("deletePending"),false)){status="deletionPending";initialized=false;emit();}else{accountChanged(true);deleteError=message;emit();}}
 private void finishAccountDeletion(String userId){generation++;if(listener!=null){listener.remove();listener=null;}SharedPreferences.Editor edit=prefs.edit();for(String name:prefs.getAll().keySet())if(name.startsWith(userId+"_"))edit.remove(name);edit.commit();uid="";pending="";remote="";remoteRevision=0;pendingBase=0;lastSync=0;initialized=false;writing=false;deleteBusy=false;deleteError="";deletionSucceeded=true;status="deleted";auth.signOut();try{KhatmaScheduler.clear(activity);PrayerSettings settings=PrayerSettings.load(activity);settings.json.put("enabled",false);settings.save(activity);PrayerScheduler.schedule(activity);}catch(Exception ignored){}try{CredentialManager.create(activity).clearCredentialStateAsync(new ClearCredentialStateRequest(),null,command->main.post(command),new CredentialManagerCallback<Void,ClearCredentialException>(){public void onResult(Void result){}public void onError(ClearCredentialException error){}});}catch(Exception ignored){}emit();}
 private String explain(Exception e){if(e instanceof FirebaseFirestoreException){FirebaseFirestoreException.Code code=((FirebaseFirestoreException)e).getCode();if(code==FirebaseFirestoreException.Code.PERMISSION_DENIED)return "تعذر الوصول إلى بيانات حسابك. أعد تسجيل الدخول، وإذا استمرت المشكلة أعد المحاولة لاحقًا.";if(code==FirebaseFirestoreException.Code.NOT_FOUND||code==FirebaseFirestoreException.Code.FAILED_PRECONDITION)return "خدمة المزامنة غير جاهزة الآن. بياناتك محفوظة على جهازك؛ أعد المحاولة لاحقًا.";}return "تعذرت المزامنة الآن. بياناتك محفوظة على هذا الجهاز وستُعاد المحاولة عند الاتصال.";}
 public boolean matchesAck(String payload){FirebaseUser user=auth.getCurrentUser();return user!=null&&payload!=null&&payload.equals(prefs.getString(user.getUid()+"_ackPayload",""));}
 public String snapshot(){if(Looper.myLooper()!=Looper.getMainLooper()){java.util.concurrent.FutureTask<String> result=new java.util.concurrent.FutureTask<>(this::snapshot);main.post(result);try{return result.get(5,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception e){return "{\"status\":\"connecting\",\"uid\":\"\"}";}}try{FirebaseUser current=auth.getCurrentUser();if(current!=null&&!current.getUid().equals(uid))return new JSONObject().put("uid",current.getUid()).put("status","connecting").put("initialized",false).toString();JSONObject j=new JSONObject().put("deleteBusy",deleteBusy).put("deleteError",deleteError).put("deletionSucceeded",deletionSucceeded).put("accountRemoved",accountRemoved).put("deletionPending",!uid.isEmpty()&&prefs.getBoolean(key("deletePending"),false)).put("status",status).put("error",error).put("revision",remoteRevision).put("pendingBase",pendingBase).put("lastSync",lastSync).put("pending",!pending.isEmpty()).put("initialized",initialized).put("loginBusy",loginBusy).put("uid",uid).put("ackInputPayload",uid.isEmpty()?"":prefs.getString(key("ackInput"),"")).put("ackRevision",uid.isEmpty()?0:prefs.getLong(key("ackRevision"),0));FirebaseUser user=auth.getCurrentUser();if(user!=null){j.put("name",user.getDisplayName()==null?"":user.getDisplayName());j.put("email",user.getEmail()==null?"":user.getEmail());}if(!remote.isEmpty())j.put("remotePayload",remote);if(!pending.isEmpty())j.put("pendingPayload",pending);return j.toString();}catch(Exception e){return "{}";}}
 private void emit(){if(closed)return;final String json=snapshot();final long session=generation;main.post(()->{if(!closed&&session==generation)web.evaluateJavascript("window.onNativeCloud&&window.onNativeCloud("+json+")",null);});}
 public void destroy(){closed=true;if(live==this)live=null;generation++;auth.removeAuthStateListener(authListener);if(listener!=null)listener.remove();if(signInSignal!=null)signInSignal.cancel();main.removeCallbacksAndMessages(null);}
}
